from collections import deque
import itertools

n = 16
known_edges = [
    (1,10), (4,10), (7,10), (1,6), (5,13), (3,6), (0,6), (0,15), (9,13), (3,12),
    (2,7), (4,14), (1,12), (8,13), (11,14), (5,12), (4,12), (5,14), (0,4), (6,7),
    (8,9), (9,12), (2,8), (10,14)
]

def add_edges_for_min_degree(n, known_edges, target_degree=5):
    edges = list(known_edges)
    degree = [0] * n
    for u, v in edges:
        degree[u] += 1
        degree[v] += 1

    changed = True
    while changed:
        changed = False
        low_deg = [(degree[v], v) for v in range(n) if degree[v] < target_degree]
        low_deg.sort()

        if not low_deg:
            break

        v1 = low_deg[0][1]
        for _, v2 in low_deg[1:]:
            if v1 < v2:
                edge = (v1, v2)
            else:
                edge = (v2, v1)

            if edge not in set(edges):
                edges.append(edge)
                degree[v1] += 1
                degree[v2] += 1
                changed = True
                break

    return edges

edges = add_edges_for_min_degree(n, known_edges)
print("Edges:", edges)

def check_vertex_connectivity(n, edges, k):
    for removed in itertools.combinations(range(n), k-1):
        remaining = [v for v in range(n) if v not in removed]
        if len(remaining) <= 1:
            continue

        adj = {v: [] for v in remaining}
        for u, v in edges:
            if u in adj and v in adj:
                adj[u].append(v)
                adj[v].append(u)

        visited = set()
        queue = deque([remaining[0]])
        visited.add(remaining[0])

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)

        if len(visited) != len(remaining):
            return False, removed

    return True, None

result, cut = check_vertex_connectivity(n, edges, 5)
print(f"Vertex connectivity >= 5: {result}")
if not result:
    print(f"Cut found: {cut}")
